// Copies the Pine contract (backend/btb/pine/REFERENCE.md) into the web app,
// which is built without the backend beside it. The copy-prompt and the MCP
// get_reference tool both read the generated file. backend/tests/
// test_pine_reference.py fails if the two ever differ, so run this after
// editing REFERENCE.md:
//
//   node scripts/sync-reference.mjs
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const md = readFileSync(join(here, '..', '..', 'backend', 'btb', 'pine', 'REFERENCE.md'), 'utf8');
const out = `/* Generated by scripts/sync-reference.mjs from backend/btb/pine/REFERENCE.md.
 * Do not edit: edit REFERENCE.md and re-run the script. */

export const PINE_REFERENCE: string = ${JSON.stringify(md)};
`;
writeFileSync(join(here, '..', 'src', 'lib', 'pineReference.ts'), out);
console.log(`wrote src/lib/pineReference.ts (${md.length} chars)`);
